      disableGameInputBlocker: disableGameInputBlocker,
      isGameInputBlocked: isGameInputBlocked,
      isSkillForbiddenForAutomation: isSkillForbiddenForAutomation,
      hasBasicAttackOnBar: hasBasicAttackOnBar,
      isAutoFarmEasyMode: isAutoFarmEasyMode,
