      getBasementState: getBasementState,
      basementSetPhase: basementSetPhase,
      markBasementEntered: markBasementEntered,
      markBasementExited: markBasementExited,
      detectBasementExitButton: detectBasementExitButton,
      detectBasementPortalActionButton: detectBasementPortalActionButton,
      detectBasementEntryButton: detectBasementEntryButton,
      maybeEnterBasementAfterMove: maybeEnterBasementAfterMove,
      isBasementPortalTile: isBasementPortalTile,
